/* 短信交互原型：所有记录均为演示数据，不连接发送服务。 */
(() => {
  const currentUser = '我', currentOrg = '集团信息技术部';
  const titles = ['9.7答辩','9.4答辩','答辩材料准备通知','产品线上研讨会邀请','认证学习进度提醒','季度客户交流会','服务升级通知','新产品体验活动','生态伙伴培训通知','会议签到提醒','认证结果通知','客户回访邀请'];
  const records = titles.map((title,i) => ({id:8694-i,title,type:i%3===0?'推广短信':'通知短信',owner:i%4===0?'我':['张宁','陈晓','李悦'][i%3],org:i%3===2?'华东营销中心':currentOrg,signature:'用友网络',date:`2026-09-${String(9-Math.floor(i/2)).padStart(2,'0')} 09:30`,status:i%5===0?'scheduled':'sent',review:i%5===0?'审核中':'审核通过',content:i<3?'用友答辩安排通知：恭喜您通过能力考试并进入认证答辩环节。请登录友认证，在“我的认证”中查看答辩时间、会议方式及材料要求。请提前完成材料上传，并准时参加。如有疑问，请联系认证工作组。':'您好！'+title+'即将开始。请通过活动详情页了解时间、地点与参与方式，提前安排好时间。感谢您的关注与支持！',count:120+i*17}));
  // 本人发布必然属于当前组织。
  records.forEach(r=>{if(r.owner===currentUser)r.org=currentOrg;});
  const states = {smsManagement:{scope:'all',query:'',type:'all',tab:'sent',page:1,size:5},smsTemplates:{scope:'all',query:'',type:'all',tab:'all',page:1,size:5}};
  let searchTimer;
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const inScope=(r,scope)=>scope==='all'||(scope==='mine'?r.owner===currentUser:scope==='current'?r.org===currentOrg:r.org!==currentOrg);
  const select=(page,ignoreScope=false)=>{const s=states[page];return records.filter(r=>(page==='smsTemplates'||r.status===s.tab)&&(ignoreScope||inScope(r,s.scope))&&(s.type==='all'||r.type===s.type)&&r.title.toLowerCase().includes(s.query.trim().toLowerCase()));};
  const dialog=document.createElement('dialog');dialog.className='sms-dialog';dialog.setAttribute('aria-labelledby','smsDialogTitle');document.body.append(dialog);
  function modal(title,body,footer=''){dialog.innerHTML=`<div class="sms-dialog-head"><h3 id="smsDialogTitle">${esc(title)}</h3><button aria-label="关闭" data-close>×</button></div><div class="sms-dialog-body">${body}</div><div class="sms-dialog-foot"><button class="ghost-button" data-close>关闭</button>${footer}</div>`;dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dialog.close());if(!dialog.open)dialog.showModal();}
  function render(page){
    const root=document.getElementById(page),s=states[page],tpl=page==='smsTemplates',all=select(page),pages=Math.max(1,Math.ceil(all.length/s.size));s.page=Math.min(s.page,pages);
    const rows=all.slice((s.page-1)*s.size,s.page*s.size);
    root.innerHTML=`<div class="sms-header"><div><h3>${tpl?'短信模板':'短信管理'}<span class="sms-demo">交互原型 · 演示数据</span></h3><p>${tpl?'管理团队短信内容，查看模板审核进度。':'查看发送记录，按发布范围快速找到目标短信。'}</p></div><button class="primary-button" data-create>${tpl?'＋ 新增模板':'＋ 发送短信'}</button></div><div class="sms-panel"><div class="sms-filters"><div class="sms-scope" role="group" aria-label="发布范围"><span class="sms-label">发布范围</span>${[['all','全部'],['mine','本人发布'],['current','所在组织发布'],['other','其他组织发布']].map(([v,l])=>`<button data-scope="${v}" aria-pressed="${s.scope===v}">${l}<b>${select(page,true).filter(r=>inScope(r,v)).length}</b></button>`).join('')}</div><form class="sms-query"><label>短信模板标题<input name="query" value="${esc(s.query)}" placeholder="请输入短信模板标题" autocomplete="off"></label><label>短信类型<select name="type">${['all','通知短信','推广短信'].map(v=>`<option value="${v}" ${s.type===v?'selected':''}>${v==='all'?'全部类型':v}</option>`).join('')}</select></label><button class="ghost-button" type="button" data-reset>重置</button></form><p class="sms-note">当前组织：${currentOrg} · 所在组织发布包含本人发布</p></div><div class="sms-tabs">${(tpl?[['all','全部模板']]:[['sent','已发送列表'],['scheduled','定时发送列表']]).map(([v,l])=>`<button data-tab="${v}" aria-pressed="${s.tab===v}">${l}</button>`).join('')}<span class="sms-summary" role="status">共 ${all.length} ${tpl?'个模板':'条记录'}</span></div><div class="sms-table-wrap"><table class="sms-table"><colgroup><col style="width:18%"><col style="width:10%"><col style="width:26%"><col style="width:15%"><col style="width:10%"><col style="width:12%"><col style="width:9%"></colgroup><thead><tr><th>模板标题 / 编码</th><th>短信类型</th><th>短信内容</th><th>发布人 / 所属组织</th><th>${tpl?'审核状态':'短信签名'}</th><th>${!tpl&&s.tab==='scheduled'?'计划发送时间':'创建时间'}</th><th>操作</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="sms-title" data-detail="${r.id}">${esc(r.title)}</button><span class="sms-sub">模板编码 ${r.id}</span></td><td><span class="sms-badge">${r.type}</span></td><td><div class="sms-excerpt">${esc(r.content)}</div><button class="sms-link" data-detail="${r.id}">查看全文</button></td><td>${r.owner===currentUser?'我（本人）':esc(r.owner)}<span class="sms-sub">${esc(r.org)}</span></td><td>${tpl?`<span class="sms-badge ${r.review==='审核通过'?'ok':'wait'}">${r.review}</span>`:r.signature}</td><td>${!tpl&&s.tab==='scheduled'?'2026-09-15':r.date.split(' ')[0]}<span class="sms-sub">09:30</span></td><td><div class="sms-actions">${tpl?`<button class="sms-link" data-copy="${r.id}">复制</button>`:s.tab==='sent'?`<button class="sms-link" data-stats="${r.id}">统计</button><button class="sms-link" data-send="${r.id}">再次发送</button>`:`<button class="sms-link" data-detail="${r.id}">详情</button>`}<button class="sms-link sms-danger" data-remove="${r.id}">${!tpl&&s.tab==='scheduled'?'取消定时':'删除'}</button></div></td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="sms-empty"><h4>没有找到匹配的短信</h4><p>试试其他模板标题，或清空筛选条件。</p><button class="ghost-button" data-reset>清空筛选</button></div>':''}</div><div class="sms-pager"><span class="sms-total" aria-live="polite">${all.length?`显示 ${(s.page-1)*s.size+1}–${Math.min(s.page*s.size,all.length)}，`:''}共 ${all.length} 条</span><select aria-label="每页条数" data-size>${[5,10,20].map(n=>`<option ${s.size===n?'selected':''} value="${n}">${n} 条/页</option>`).join('')}</select><button data-prev ${s.page===1?'disabled':''} aria-label="上一页">上一页</button><span>${s.page} / ${pages}</span><button data-next ${s.page===pages?'disabled':''} aria-label="下一页">下一页</button></div></div>`;
    root.querySelector('form').onsubmit=e=>{e.preventDefault();s.query=e.target.query.value;s.type=e.target.type.value;s.page=1;render(page);};
    root.querySelector('[name=query]').oninput=e=>{const value=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{s.query=value;s.page=1;render(page);const input=root.querySelector('[name=query]');input.focus();input.setSelectionRange(value.length,value.length);},180);};
    root.querySelector('[name=type]').onchange=e=>{s.type=e.target.value;s.query=root.querySelector('[name=query]').value;s.page=1;render(page);};
    root.querySelectorAll('[data-scope]').forEach(b=>b.onclick=()=>{s.scope=b.dataset.scope;s.page=1;render(page);});
    root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{s.tab=b.dataset.tab;s.page=1;render(page);});
    root.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>{Object.assign(s,{scope:'all',query:'',type:'all',page:1});render(page);});
    root.querySelector('[data-size]').onchange=e=>{s.size=Number(e.target.value);s.page=1;render(page);};
    root.querySelector('[data-prev]').onclick=()=>{s.page--;render(page);};root.querySelector('[data-next]').onclick=()=>{s.page++;render(page);};
    root.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{const r=records.find(r=>r.id===+b.dataset.detail);modal(r.title,`<dl><dt>模板编码</dt><dd>${r.id}</dd><dt>短信类型</dt><dd>${r.type}</dd><dt>发布人</dt><dd>${esc(r.owner)} · ${esc(r.org)}</dd><dt>短信签名</dt><dd>${r.signature}</dd></dl><hr><p>${esc(r.content)}</p>`);});
    root.querySelectorAll('[data-stats]').forEach(b=>b.onclick=()=>{const r=records.find(r=>r.id===+b.dataset.stats);modal('发送统计',`<p>${esc(r.title)}</p><dl><dt>发送人数</dt><dd>${r.count}</dd><dt>成功</dt><dd>${r.count-2}</dd><dt>失败</dt><dd>2</dd></dl><p class="sms-note">演示统计，不代表真实发送结果。</p>`);});
    root.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const r=records.find(r=>r.id===+b.dataset.remove);modal(b.textContent,`<p>确认${b.textContent}演示记录“${esc(r.title)}”？刷新页面可恢复。</p>`,`<button class="primary-button" id="smsRemoveConfirm">确认${b.textContent}</button>`);dialog.querySelector('#smsRemoveConfirm').onclick=()=>{records.splice(records.indexOf(r),1);dialog.close();renderAll();};});
    root.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>edit(records.find(r=>r.id===+b.dataset.copy)));
    root.querySelectorAll('[data-send]').forEach(b=>b.onclick=()=>send(records.find(r=>r.id===+b.dataset.send)));
    root.querySelector('[data-create]').onclick=()=>tpl?edit():send();
  }
  function edit(r){modal(r?'复制为新模板':'新增模板',`<form id="smsEdit" class="sms-form"><label>模板标题<input name="title" maxlength="80" required value="${r?esc(r.title)+'（副本）':''}"></label><label>短信类型<select name="type"><option>通知短信</option><option>推广短信</option></select></label><label>短信内容<textarea name="content" required maxlength="1000">${r?esc(r.content):''}</textarea></label><p class="sms-note">保存为演示模板，刷新后恢复；不会提交真实审核。</p></form>`,`<button class="primary-button" type="submit" form="smsEdit">保存演示模板</button>`);if(r)dialog.querySelector('[name=type]').value=r.type;dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const f={title:e.target.elements.namedItem('title'),content:e.target.elements.namedItem('content'),type:e.target.elements.namedItem('type')}; if(!f.title.value.trim()||!f.content.value.trim())return;records.unshift({id:Math.max(...records.map(x=>x.id),8694)+1,title:f.title.value.trim(),type:f.type.value,content:f.content.value,org:currentOrg,owner:currentUser,signature:'用友网络',date:'2026-09-09 09:30',status:'draft',review:'审核中',count:0});dialog.close();renderAll();};}
  function send(r){
    const approved=records.filter(x=>x.review==='审核通过');
    const groups=[{id:'g1',name:'认证答辩通知组',people:Array.from({length:128},(_,i)=>i)},{id:'g2',name:'生态伙伴培训组',people:Array.from({length:86},(_,i)=>i+100)},{id:'g3',name:'待完善的客户分组',people:[]}];
    const tags=[{id:'t1',name:'已报名',people:Array.from({length:64},(_,i)=>i+60)},{id:'t2',name:'高意向客户',people:Array.from({length:42},(_,i)=>i+180)},{id:'t3',name:'新建标签',people:[]}];
    const picked=new Set();let selected=approved.includes(r)?r:null;
    const cnNow=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());
    modal('发送短信',`<div class="sms-compose"><section><h4>1. 选择短信模板</h4><label class="sms-field">搜索模板<input id="smsTemplateSearch" placeholder="搜索模板标题" type="search"></label><div id="smsTemplateOptions" class="sms-template-options" role="group" aria-label="短信模板"></div><div id="smsChosenTemplate" class="sms-chosen"></div></section><section><h4>2. 选择发送对象</h4><p class="sms-note">分组与标签取并集，同一用户仅计入一次。空人群不可选。</p><label class="sms-field">搜索分组或标签<input id="smsAudienceSearch" type="search" placeholder="输入分组或标签名称"></label><div class="sms-audience-columns"><div><h5>分组</h5><div id="smsGroupOptions"></div></div><div><h5>标签</h5><div id="smsTagOptions"></div></div></div><div id="smsAudienceSummary" class="sms-audience-summary" aria-live="polite"></div></section><section><h4>3. 设置发送时间</h4><div class="sms-send-mode"><label><input type="radio" name="smsMode" value="now" checked> 立即发送</label><label><input type="radio" name="smsMode" value="later"> 定时发送</label></div><div id="smsScheduleFields" hidden><div class="sms-schedule"><label class="sms-field">发送日期<input id="smsSendDate" type="date" min="${cnNow().slice(0,10)}"></label><label class="sms-field">发送时间<select id="smsSendTime"><option value="">请选择时间</option></select></label></div><p class="sms-note">北京时间（UTC+8），以15分钟为间隔，仅可选择未来时间。</p></div><p id="smsSendError" role="alert" class="sms-send-error"></p></section><p class="sms-note">交互原型：人群与模板均为演示数据，不会发送真实短信或产生费用。</p></div>`,`<button class="primary-button" id="smsReviewSend">预览并确认</button>`);
    dialog.classList.add('sms-compose-dialog');dialog.addEventListener('close',()=>dialog.classList.remove('sms-compose-dialog'),{once:true});
    const get=id=>dialog.querySelector('#'+id), mode=()=>dialog.querySelector('[name=smsMode]:checked').value;
    const audience=()=>[...groups,...tags].filter(x=>picked.has(x.id));
    const count=()=>new Set(audience().flatMap(x=>x.people)).size;
    function templates(){const q=get('smsTemplateSearch').value.trim().toLowerCase();const matches=approved.filter(x=>x.title.toLowerCase().includes(q));get('smsTemplateOptions').innerHTML=matches.map(x=>`<button type="button" class="sms-template-option" data-template="${x.id}" aria-pressed="${selected===x}"><span><strong>${esc(x.title)}</strong><small>${x.type} · ${x.signature}</small></span><span><small>创建人：${esc(x.owner)}</small><small>创建时间：${x.date}</small></span></button>`).join('')||'<p class="sms-note">未找到匹配模板，请更换搜索词。</p>';get('smsTemplateOptions').querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=approved.find(x=>x.id===+b.dataset.template);templates();get('smsSendError').textContent='';});get('smsChosenTemplate').innerHTML=selected?`<div class="sms-selected-heading"><strong>已选：${esc(selected.title)}</strong><span>${selected.type} · ${selected.signature}</span></div><p>${esc(selected.content)}</p><small>创建人：${esc(selected.owner)} · 创建时间：${selected.date}</small>`:'<p class="sms-note">请选择模板，选择后可预览完整内容。</p>';}
    function people(){const q=get('smsAudienceSearch').value.trim();[[groups,'smsGroupOptions'],[tags,'smsTagOptions']].forEach(([list,id])=>{get(id).innerHTML=list.filter(x=>x.name.includes(q)).map(x=>`<label class="sms-person-option ${x.people.length?'':'is-empty'}"><input type="checkbox" value="${x.id}" ${picked.has(x.id)?'checked':''} ${x.people.length?'':'disabled'}><span>${x.name}<small>${x.people.length?'':'暂无成员，不可选择'}</small></span><b>${x.people.length} 人</b></label>`).join('')||'<p class="sms-note">无匹配结果</p>';get(id).querySelectorAll('input').forEach(el=>el.onchange=()=>{el.checked?picked.add(el.value):picked.delete(el.value);summary();get('smsSendError').textContent='';});});summary();}
    function summary(){const sum=audience().reduce((n,x)=>n+x.people.length,0);get('smsAudienceSummary').textContent=`已选 ${audience().length} 个人群 · 合计 ${sum} 人 · 重复 ${sum-count()} 人 · 去重后预计发送 ${count()} 人`;}
    function times(){const date=get('smsSendDate').value,now=cnNow(),old=get('smsSendTime').value;get('smsSendDate').min=now.slice(0,10);get('smsSendTime').innerHTML='<option value="">请选择时间</option>'+Array.from({length:96},(_,i)=>`${String(Math.floor(i/4)).padStart(2,'0')}:${String(i%4*15).padStart(2,'0')}`).map(t=>`<option value="${t}" ${!date||date+' '+t<=now?'disabled':''}>${t}</option>`).join('');if(date&&date+' '+old>now)get('smsSendTime').value=old;if(date&&date<now.slice(0,10)){get('smsSendDate').value='';get('smsSendError').textContent='发送日期不能早于今天，请重新选择。';} }
    get('smsTemplateSearch').oninput=templates;get('smsAudienceSearch').oninput=people;
    dialog.querySelectorAll('[name=smsMode]').forEach(el=>el.onchange=()=>{get('smsScheduleFields').hidden=mode()!=='later';get('smsSendError').textContent='';times();});
    get('smsSendDate').onchange=times;get('smsSendDate').onfocus=()=>{get('smsSendDate').min=cnNow().slice(0,10);};get('smsSendTime').onfocus=times;
    function validate(){if(!selected)return '请选择短信模板。';if(!count())return '请至少选择一个有成员的分组或标签。';if(mode()==='later'&&(!get('smsSendDate').value||!get('smsSendTime').value||get('smsSendDate').value+' '+get('smsSendTime').value<=cnNow()))return '请选择晚于当前时间的发送日期和时间。';return '';}
    get('smsReviewSend').onclick=()=>{const error=validate();get('smsSendError').textContent=error;if(error)return;const scheduled=mode()==='later',when=scheduled?get('smsSendDate').value+' '+get('smsSendTime').value:'立即发送';const review=document.createElement('div');review.className='sms-review';review.innerHTML=`<h4>发送确认</h4><dl><dt>短信模板</dt><dd>${esc(selected.title)}</dd><dt>发送人群</dt><dd>${audience().map(x=>esc(x.name)).join('、')}</dd><dt>去重后人数</dt><dd>${count()} 人</dd><dt>发送时间</dt><dd>${when}${scheduled?'（北京时间）':''}</dd></dl><p>${esc(selected.content)}</p><p class="sms-note">确认后仅演示完成状态，不会发送短信。</p><button class="ghost-button" id="smsBackEdit">返回修改</button> <button class="primary-button" id="smsConfirmDemo">确认演示</button>`;dialog.querySelector('.sms-compose').hidden=true;get('smsReviewSend').hidden=true;dialog.querySelector('.sms-dialog-body').append(review);review.querySelector('#smsBackEdit').onclick=()=>{review.remove();dialog.querySelector('.sms-compose').hidden=false;get('smsReviewSend').hidden=false;};review.querySelector('#smsConfirmDemo').onclick=()=>{if(scheduled&&when<=cnNow()){review.querySelector('#smsBackEdit').onclick();get('smsSendError').textContent='所选时间已过期，请重新选择未来时间。';return;}modal('演示完成','<p>已完成发送流程预览，未发送真实短信。</p>');};};
    templates();people();times();
  }
  function renderAll(){Object.keys(states).forEach(render);}
  renderAll();
  const route=()=>{const key=location.hash.slice(1);if(states[key])showPage(key);};
  window.addEventListener('hashchange',route);route();
  document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{if(states[b.dataset.page])history.replaceState(null,'','#'+b.dataset.page);else if(states[location.hash.slice(1)])history.replaceState(null,'',location.pathname+location.search);}));
})();
